"""Regenerate native brand defaults and retint the editable logo from brand.json."""
from pathlib import Path
import json
import re
ROOT = Path(__file__).resolve().parents[1]
brand = json.loads((ROOT/'assets/brand.json').read_text(encoding='utf-8'))
accent = brand['accent'].lower()
if not re.fullmatch(r'#[0-9a-f]{6}', accent):
    raise ValueError('Expected a six-digit RGB accent')
(ROOT/'include/brand.hpp').write_text(
    '// Generated by tools/sync_brand.py from assets/brand.json.\n'
    '#pragma once\n#include <cstdint>\nnamespace sm {\n'
    f'inline constexpr uint32_t default_accent=0x{accent[1:]};\n'
    f'inline constexpr const char* default_accent_name={json.dumps(brand["name"])};\n'
    '}\n', encoding='utf-8')
p=ROOT/'assets/boot_logo.svg'
text=p.read_text(encoding='utf-8')
text=re.sub(r'(<g id="accent"[^>]*stroke=")[^"]+("[^>]*>)',lambda m:m[1]+accent+m[2],text)
text=re.sub(r'(<g id="accent-dots"[^>]*fill=")[^"]+("[^>]*>)',lambda m:m[1]+accent+m[2],text)
p.write_text(text,encoding='utf-8')
print('Synchronized brand:',accent)
